import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from './AuthContext';

function MalwareLab() {
  const navigate = useNavigate();
  const { token: authToken } = useAuth();
  const isLoggedIn = !!authToken;
  const [file, setFile] = useState(null);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [history, setHistory] = useState([]);
  const [fraudReports, setFraudReports] = useState([]);
  const [loading, setLoading] = useState(false);
  const [filter, setFilter] = useState('all');

  useEffect(() => {
    if (authToken) {
      fetchHistory();
      fetchFraudReports();
    }
  }, [authToken]);

  const fetchHistory = async () => {
    try {
      const res = await axios.get('/api/malware/history');
      setHistory(res.data.history || []);
    } catch (err) {
      console.error('Failed to fetch history:', err);
    }
  };

  const fetchFraudReports = async () => {
    try {
      const res = await axios.get('/api/malware/fraud-reports');
      setFraudReports(res.data.fraud_reports || []);
    } catch (err) {
      console.error('Failed to fetch fraud reports:', err);
    }
  };

  const upload = async () => {
    setError(null);
    setResult(null);

    if (!authToken) {
      setError('You must be logged in to run a scan. Please go to the Secure Web App and login.');
      return;
    }

    if (!file) {
      setError('Please select a file to scan.');
      return;
    }

    setLoading(true);

    const formData = new FormData();
    formData.append('file', file);

    try {
      const res = await axios.post('/api/malware/scan', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setResult(res.data);
      fetchHistory(); // refresh history
      if (res.data.fraud_detected) {
        fetchFraudReports(); // refresh fraud reports
      }
    } catch (err) {
      const msg =
        err.response?.data?.error ||
        (err.response?.data && JSON.stringify(err.response.data)) ||
        err.message ||
        'Scan failed.';
      setError(`Scan failed: ${msg}`);
    } finally {
      setLoading(false);
    }
  };

  const filteredHistory = history.filter(scan => {
    if (filter === 'all') return true;
    if (filter === 'malicious') return scan.status === 'MALICIOUS';
    if (filter === 'suspicious') return scan.status === 'SUSPICIOUS';
    if (filter === 'fraud') return scan.fraud_detected;
    return true;
  });

  return (
    <div className="container-fluid">
      <div className="row">
        <div className="col-12">
          <div className="d-flex justify-content-between align-items-center mb-3">
            <div>
              <h2 className="mb-1">Malware Analysis Lab</h2>
              <small className="text-muted">Upload a suspicious file and run analysis using the built-in scanner.</small>
            </div>
            <div className="d-flex align-items-center gap-2">
              <span className={`badge ${isLoggedIn ? 'bg-success' : 'bg-warning'}`}>
                {isLoggedIn ? 'Logged in' : 'Not logged in'}
              </span>
              {!isLoggedIn && (
                <button className="btn btn-sm btn-outline-light" onClick={() => navigate('/auth')}>
                  Login
                </button>
              )}
              <button className="btn btn-sm btn-outline-light" onClick={() => window.location.reload()}>
                Reset
              </button>
            </div>
          </div>
        </div>
      </div>

      <ul className="nav nav-tabs mb-4" id="malwareTabs" role="tablist">
        <li className="nav-item" role="presentation">
          <button className="nav-link active" id="upload-tab" data-bs-toggle="tab" data-bs-target="#upload" type="button" role="tab" aria-controls="upload" aria-selected="true">Upload & Scan</button>
        </li>
        <li className="nav-item" role="presentation">
          <button className="nav-link" id="history-tab" data-bs-toggle="tab" data-bs-target="#history" type="button" role="tab" aria-controls="history" aria-selected="false">Scan History</button>
        </li>
        <li className="nav-item" role="presentation">
          <button className="nav-link" id="fraud-tab" data-bs-toggle="tab" data-bs-target="#fraud" type="button" role="tab" aria-controls="fraud" aria-selected="false">Fraud Reports</button>
        </li>
      </ul>

      <div className="tab-content" id="malwareTabsContent">
        <div className="tab-pane fade show active" id="upload" role="tabpanel" aria-labelledby="upload-tab">
          <div className="row">
            <div className="col-lg-6 col-md-12 mb-4">
              <div className="card h-100">
                <div className="card-body">
                  <h5 className="card-title">Upload & Scan</h5>
                  <div className="mb-3">
                    <label className="form-label">Upload suspicious file</label>
                    <div className="input-group input-group-lg">
                      <input
                        className="form-control"
                        type="file"
                        onChange={(e) => setFile(e.target.files[0])}
                        accept=".exe,.dll,.pdf,.doc,.docx,.xls,.xlsx,.zip,.rar"
                      />
                      <span className="input-group-text" style={{ minWidth: '220px' }}>
                        {file ? file.name : 'No file chosen'}
                      </span>
                    </div>
                  </div>
                  <button className="btn btn-primary w-100" onClick={upload} disabled={loading || !authToken}>
                    {loading ? (
                      <>
                        <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true" />
                        Scanning...
                      </>
                    ) : (
                      'Run Analysis'
                    )}
                  </button>

                  {error && <div className="alert alert-danger mt-3">{error}</div>}

                  {!authToken && (
                    <div className="alert alert-warning mt-3">
                      <strong>Log in required:</strong> use the Secure Web App module to authenticate before scanning.
                    </div>
                  )}
                </div>
              </div>
            </div>

            <div className="col-lg-6 col-md-12 mb-4">
              {result && (
                <div className="card bg-dark text-white">
                  <div className="card-body">
                    <h4 className="card-title">Scan Result</h4>
                    <div className="row">
                      <div className="col-md-6">
                        <p className="mb-1">
                          <strong>Status:</strong>{' '}
                          <span
                            className={
                              result.status === 'MALICIOUS'
                                ? 'text-danger'
                                : result.status === 'SUSPICIOUS'
                                ? 'text-warning'
                                : 'text-success'
                            }
                          >
                            {result.status}
                          </span>
                        </p>
                        <p className="mb-1">
                          <strong>File:</strong> {result.file_name}
                        </p>
                        <p className="mb-1">
                          <strong>Type:</strong> {result.file_type || 'Unknown'}
                        </p>
                        <p className="mb-1">
                          <strong>Size:</strong> {result.file_size} bytes
                        </p>
                        <p className="mb-1">
                          <strong>Entropy:</strong> {result.entropy}
                        </p>
                      </div>
                      <div className="col-md-6">
                        <p className="mb-1">
                          <strong>SHA256:</strong> <code className="text-break">{result.sha256}</code>
                        </p>
                        <p className="mb-1">
                          <strong>MD5:</strong> <code>{result.md5}</code>
                        </p>
                        <p className="mb-1">
                          <strong>SHA1:</strong> <code>{result.sha1}</code>
                        </p>
                      </div>
                    </div>

                    {result.indicators && result.indicators.length > 0 && (
                      <div className="mt-3">
                        <h6>Suspicious Indicators</h6>
                        <ul>
                          {result.indicators.map((indicator, idx) => (
                            <li key={idx}>{indicator}</li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {result.scan_id && (
                      <div className="mt-3">
                        <a
                          href={`/api/malware/report/${result.scan_id}?download=1`}
                          className="btn btn-outline-light btn-sm"
                        >
                          Download Full Report
                        </a>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="tab-pane fade" id="history" role="tabpanel" aria-labelledby="history-tab">
          <div className="row">
            <div className="col-12">
              <div className="card bg-dark text-white">
                <div className="card-body">
                  <div className="d-flex justify-content-between align-items-center mb-3">
                    <h5 className="card-title">Scan History</h5>
                    <div className="btn-group" role="group">
                      <input type="radio" className="btn-check" name="filter" id="all" autoComplete="off" checked={filter === 'all'} onChange={() => setFilter('all')} />
                      <label className="btn btn-outline-light btn-sm" htmlFor="all">All</label>
                      <input type="radio" className="btn-check" name="filter" id="malicious" autoComplete="off" checked={filter === 'malicious'} onChange={() => setFilter('malicious')} />
                      <label className="btn btn-outline-light btn-sm" htmlFor="malicious">Malicious</label>
                      <input type="radio" className="btn-check" name="filter" id="suspicious" autoComplete="off" checked={filter === 'suspicious'} onChange={() => setFilter('suspicious')} />
                      <label className="btn btn-outline-light btn-sm" htmlFor="suspicious">Suspicious</label>
                      <input type="radio" className="btn-check" name="filter" id="fraud" autoComplete="off" checked={filter === 'fraud'} onChange={() => setFilter('fraud')} />
                      <label className="btn btn-outline-light btn-sm" htmlFor="fraud">Fraud</label>
                    </div>
                  </div>
                  {filteredHistory.length === 0 ? (
                    <p className="text-muted">No scans yet.</p>
                  ) : (
                    <div className="table-responsive">
                      <table className="table table-dark table-striped">
                        <thead>
                          <tr>
                            <th>File</th>
                            <th>Status</th>
                            <th>Scanned At</th>
                            <th>Action</th>
                          </tr>
                        </thead>
                        <tbody>
                          {filteredHistory.map((scan) => (
                            <tr key={scan.id}>
                              <td>{scan.filename}</td>
                              <td>
                                <span
                                  className={
                                    scan.status === 'MALICIOUS'
                                      ? 'text-danger'
                                      : scan.status === 'SUSPICIOUS'
                                      ? 'text-warning'
                                      : 'text-success'
                                  }
                                >
                                  {scan.status}
                                </span>
                              </td>
                              <td>{new Date(scan.scanned_at).toLocaleString()}</td>
                              <td>
                                <a
                                  href={`/api/malware/report/${scan.id}?download=1`}
                                  className="btn btn-outline-light btn-sm"
                                >
                                  Download
                                </a>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="tab-pane fade" id="fraud" role="tabpanel" aria-labelledby="fraud-tab">
          <div className="row">
            <div className="col-12">
              <div className="card bg-dark text-white">
                <div className="card-body">
                  <h5 className="card-title">Fraud Detection Reports</h5>
                  {fraudReports.length === 0 ? (
                    <p className="text-muted">No fraud detections yet.</p>
                  ) : (
                    <div className="table-responsive">
                      <table className="table table-dark table-striped">
                        <thead>
                          <tr>
                            <th>File</th>
                            <th>Status</th>
                            <th>Scanned At</th>
                            <th>Action</th>
                          </tr>
                        </thead>
                        <tbody>
                          {fraudReports.map((scan) => (
                            <tr key={scan.id}>
                              <td>{scan.filename}</td>
                              <td>
                                <span className="text-warning">{scan.status}</span>
                              </td>
                              <td>{new Date(scan.scanned_at).toLocaleString()}</td>
                              <td>
                                <a
                                  href={`/api/malware/report/${scan.id}?download=1`}
                                  className="btn btn-outline-light btn-sm"
                                >
                                  Download
                                </a>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default MalwareLab;
